INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (1, 0, 11, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 0, 72, 0, 72021, 10, 1, 1);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (0, "", 91, "", "", 72, "", 72022, 0, "", 0);
