INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (1, 0, 11, "そりゃそうですよね……\nいきなり前のめり過ぎ太郎でした……", 0, 72, 0, 72033, 10, 1, 1);
