INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES ("vo_asb", "", 21, "vo_asb_0823", "", 82, "", 82020, 0, "", 0);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (1, 0, 11, "それでも……適性など踏み越えて、\n己の道を突き進むのが冒険者です。\n一度決めたことを、\n曲げるわけには参りません……！", 0, 82, 0, 82021, 10, 1, 1);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (0, "", 91, "", "", 82, "", 82022, 0, "", 0);
